 2	method FindMax(a: array<int>) returns (max_idx: nat)
 3		requires a.Length > 0
 4		ensures 0 <= max_idx < a.Length
 5		ensures forall j :: 0 <= j < a.Length ==> a[max_idx] >= a[j]
 6	{
 7		max_idx := 0;
 8		var i: nat := 1;
 9		while i < a.Length
10			decreases a.Length - i
11			invariant 1 <= i <= (a.Length) + 1
12			invariant 0 <= max_idx < i
13			invariant forall j :: 0 <= j < i ==> a[max_idx] >= a[j]
14		{
15			if a[i] > a[max_idx]
16			{
17				max_idx := i;
18			}
19			i := i + 1;
20		}
21		return max_idx;
22	}
23	
24	method Main()
25	{
26		var arr: array<int> := new int[][1, 1, 25, 7, 2, -2, 3, 3, 20];
27		var idx := FindMax(arr);
28	
29		assert forall i :: 0 <= i < arr.Length ==> arr[idx] >= arr[i];
30		// apparently I can't assert definite values like
31		// assert idx == 2
32		// or assert arr[idx] == 25
33	}
